// Índice de Superação, colocação final, zebras, resumo para compartilhar e entrada da Galeria de Campeões.
// Tudo é derivado do estado do torneio e das probabilidades do próprio motor (posturas neutras).
import { PHASE_LABEL, baseOdds, isDecided, isUser, team, winnerId } from './core';
import { describeConfig, qualifiedCount } from './config';
import { sortGroupIds } from './groups';
import { DIFF, easiestDiff } from './live';
import { hasPens, sideOdds } from './model';
import { lastDecisiveMatch, playedMatches, roundTitle } from './tournament';
import type { Difficulty, PlayableMatch, Skill, Stats, Tournament } from './types';

const sideOf = (m: PlayableMatch, id: string): 'home' | 'away' => (m.home === id ? 'home' : 'away');

/** Chance (antes do jogo, posturas neutras) do resultado que o clube conseguiu; null = não pontua */
export function achievedChance(t: Tournament, m: PlayableMatch, id: string): number | null {
  if (!m.res || (m.home !== id && m.away !== id)) return null;
  const o = sideOdds(baseOdds(t, m), sideOf(m, id));
  if (m.kind === 'group') {
    const mine = m.home === id ? m.res.gH : m.res.gA, theirs = m.home === id ? m.res.gA : m.res.gH;
    if (mine > theirs) return o.win;
    if (mine === theirs) return o.win + o.draw;
    return null;
  }
  return isDecided(m) && winnerId(m) === id ? o.adv ?? null : null;
}

/** Pontos de Superação de um jogo: 100 × log2(1/p), onde p é a chance de ir tão bem quanto foi */
export function superPoints(t: Tournament, m: PlayableMatch, id: string): number {
  const p = achievedChance(t, m, id);
  return p === null || p <= 0 ? 0 : Math.round(100 * Math.log2(1 / p));
}

export const clubMatches = (t: Tournament, id: string): PlayableMatch[] => playedMatches(t).filter(m => m.home === id || m.away === id);

/** O registro ao vivo é do lado que o usuário controlou (num jogo entre dois clubes seus, só um deles jogou) */
export function liveFor(t: Tournament, m: PlayableMatch, side: 'home' | 'away'): boolean {
  const lv = m.res?.live;
  if (!lv || typeof lv !== 'object') return false;
  if (lv.s) return lv.s === side;
  return isUser(t, m[side]) && !isUser(t, m[side === 'home' ? 'away' : 'home']);
}

/** Jogos do clube jogados ao vivo de verdade: o lado dele, sem "Pular para o Fim" nem "Simular Pênaltis" */
export const fullyLive = (t: Tournament, m: PlayableMatch, id: string): boolean =>
  liveFor(t, m, m.home === id ? 'home' : 'away') && m.res!.live!.sk === 0 && !m.res!.live!.sp;

export const superTotal = (t: Tournament, id: string): number => clubMatches(t, id).reduce((s, m) => s + superPoints(t, m, id), 0);

/** "1 em N": a chance de ir tão bem em cada um destes jogos, um a um */
export const superOneIn = (score: number): number => Math.max(1, 2 ** (score / 100));

export interface Placement { rank: number; label: string }

/** Até onde o clube chegou: [etapa, desempate dentro da etapa] (maior = foi mais longe) */
function progressOf(t: Tournament, id: string, groupPos: (g: string, id: string) => number): [number, number] {
  if (t.champion === id) return [1e6, 0];
  if (t.runnerUp === id) return [1e6 - 1, 0];
  if (t.bracket) {
    const ns = t.bracket.nodes.filter(n => n.played && (n.home === id || n.away === id));
    if (ns.length) return [1000 + Math.max(...ns.map(n => n.round)), 0];
  }
  for (let k = t.knockout.length - 1; k >= 0; k--) {
    if (t.knockout[k].matches.some(m => m.home === id || m.away === id)) return [1000 + k, 0];
  }
  const x = team(t, id);
  if (x.group && t.groups[x.group]) return [0, -groupPos(x.group, id)];
  return [0, x.sw * 100 - x.sl];
}

/**
 * Colocação comparável entre torneios e formatos: pela posição final (1º = campeão; quem caiu na mesma etapa
 * divide a posição). rank = 1001 − posição, maior = melhor. Funciona em saves antigos.
 */
export function placementOf(t: Tournament, id: string): Placement {
  const orders: Record<string, string[]> = {};
  const groupPos = (g: string, x: string) => (orders[g] ??= sortGroupIds(t, g)).indexOf(x) + 1;
  const ids = Object.keys(t.teams);
  const prog = Object.fromEntries(ids.map(x => [x, progressOf(t, x, groupPos)])) as Record<string, [number, number]>;
  const cmp = (a: [number, number], b: [number, number]) => a[0] - b[0] || a[1] - b[1];
  const mine = prog[id];
  const place = 1 + ids.filter(x => cmp(prog[x], mine) > 0).length;
  const ties = ids.filter(x => cmp(prog[x], mine) === 0).length;
  const pos = ties > 1 ? `${place}º–${place + ties - 1}º` : `${place}º`;
  const of = ` de ${ids.length}`;
  let stage: string;
  if (t.champion === id) stage = 'Campeão';
  else if (t.runnerUp === id) stage = 'Vice-campeão';
  else {
    stage = '';
    if (t.bracket) {
      const ns = t.bracket.nodes.filter(n => n.played && (n.home === id || n.away === id));
      if (ns.length) stage = ns.reduce((a, b) => (b.round > a.round ? b : a)).label;
    }
    if (!stage) for (let k = t.knockout.length - 1; k >= 0 && !stage; k--) {
      if (t.knockout[k].matches.some(m => m.home === id || m.away === id)) stage = t.knockout[k].label;
    }
    if (!stage) {
      const x = team(t, id);
      if (x.group && t.groups[x.group]) {
        const gp = groupPos(x.group, id);
        stage = qualifiedCount(t.config) === 1 ? `${gp}º nos pontos corridos` : `${gp}º do Grupo ${x.group}`;
      } else if (t.config.initialPhase === 'swiss') stage = `Sistema Suíço (${x.sw}-${x.sl})`;
      else if (t.bracket?.nodes.some(n => n.home === id || n.away === id)) stage = 'Dupla Eliminação';
      else if (t.draw) stage = `aguardando o sorteio (${t.draw.phase === 'DE' ? 'Dupla Eliminação' : PHASE_LABEL[t.draw.phase]})`;
      else stage = 'Mata-mata';
    }
  }
  const alive = t.phase !== 'END' && team(t, id).out === null; // ainda no torneio: a posição não está definida
  return { rank: 1001 - place, label: stage === 'Campeão' || stage === 'Vice-campeão' || alive ? stage : `${stage} (${pos}${of})` };
}

export interface Upset { m: PlayableMatch; p: number }

/** Zebras: vencedor que tinha menos de 35% de chance pelo motor (posturas neutras), da maior para a menor */
export function upsets(t: Tournament, limit = 0.35): Upset[] {
  return playedMatches(t)
    .filter(isDecided)
    .map(m => {
      const w = winnerId(m);
      const o = sideOdds(baseOdds(t, m), sideOf(m, w));
      return { m, p: m.kind === 'group' ? o.win : o.adv ?? o.win };
    })
    .filter(u => u.p < limit)
    .sort((a, b) => a.p - b.p);
}

export const biggestUpset = (t: Tournament): Upset | null => upsets(t)[0] ?? null;

export const pctBR = (p: number, digits = 0): string => (p * 100).toFixed(digits).replace('.', ',') + '%';

/** Placar curto: "Flamengo 2 x 1 Benfica (prorr., pên. 4-3)" */
export function scoreLine(t: Tournament, m: PlayableMatch): string {
  const r = m.res!;
  const extra = hasPens(r) ? ` (${r.et ? 'prorr., ' : ''}pên. ${r.penH}-${r.penA})` : r.et ? ' (prorr.)' : '';
  return `${team(t, m.home).name} ${r.gH} x ${r.gA} ${team(t, m.away).name}${extra}`;
}

/** Dificuldade a registrar: a mais fácil usada nos jogos ao vivo (senão a configurada) */
export const recordDiff = (t: Tournament): Difficulty => easiestDiff(t.diffUsed, t.config.difficulty ?? 'normal');

function resultSquare(m: PlayableMatch, id: string): string {
  const r = m.res!;
  const mine = m.home === id ? r.gH : r.gA, theirs = m.home === id ? r.gA : r.gH;
  // pênaltis contam como empate, como na campanha
  return mine > theirs ? '🟩' : mine < theirs ? '🟥' : '🟨';
}

/** Resumo de texto (≈700 caracteres) só com fatos do estado + aviso de que é simulação */
export function buildShareText(t: Tournament): string {
  const lines: string[] = [];
  const done = t.phase === 'END';
  lines.push('🏆 Mundial de Clubes 64 (simulação)' + (done ? '' : ' · em andamento · ' + roundTitle(t)));
  if (done && t.champion) {
    const C = team(t, t.champion);
    lines.push(`Campeão: ${C.name} (OVR ${C.ovr})${t.runnerUp ? ' · Vice: ' + team(t, t.runnerUp).name : ''}`);
  }
  const fmt = describeConfig(t.config);
  lines.push(`Formato: ${fmt.ok ? fmt.text : '—'} · minigames: ${DIFF[recordDiff(t)].label}`);
  const f = done ? lastDecisiveMatch(t) : null;
  if (f && f.res) lines.push(`Final: ${scoreLine(t, f)}`);
  t.userIds.slice(0, 8).forEach(id => {
    const x = team(t, id);
    const status = t.champion === id ? 'Campeão 🏆' : x.out ?? 'segue vivo: ' + placementOf(t, id).label;
    const squares = clubMatches(t, id).map(m => resultSquare(m, id)).join('');
    lines.push(`• ${x.name} — ${status}${squares ? ' ' + squares : ''} · Superação ${superTotal(t, id)}`);
  });
  const u = biggestUpset(t);
  if (u) lines.push(`Maior zebra: ${scoreLine(t, u.m)} (o motor dava ${pctBR(u.p)})`);
  lines.push('Resultados gerados pelo simulador; não são jogos reais.');
  let txt = lines.join('\n');
  // limite de tamanho: corta linhas de clubes do fim antes do aviso
  while (txt.length > 900 && lines.length > 4) {
    lines.splice(lines.length - 2, 1);
    txt = lines.join('\n');
  }
  return txt;
}

// ---------- Galeria de Campeões ----------

export interface ClubSnap { id: string; name: string; country: string; ovr: number }
export interface HofUser extends ClubSnap, Placement { st: Stats; sup: number; live: number }
export interface HofEntry {
  id: string;
  /** versão da escala de colocação (2 = 1001 − posição final) */
  rv?: number;
  at: number;
  fmt: string;
  diff: Difficulty;
  n: number;
  champ: ClubSnap;
  vice: ClubSnap | null;
  note: string | null;
  final: { stage: string; score: string } | null;
  users: HofUser[];
  skill?: Skill;
  share: string;
}
export interface Hof {
  v: 1;
  list: HofEntry[];
  titles: Record<string, { name: string; t: number; f: number }>;
  /** torneios mais antigos que saíram da lista (os títulos continuam contados) */
  dropped?: number;
}

export const emptyHof = (): Hof => ({ v: 1, list: [], titles: {} });

const snap = (t: Tournament, id: string): ClubSnap => {
  const x = team(t, id);
  return { id: x.id, name: x.name, country: x.country, ovr: x.ovr };
};

export function hofEntry(t: Tournament, now = Date.now()): HofEntry {
  const f = qualifiedCount(t.config) === 1 && t.config.initialPhase === 'groups' ? null : lastDecisiveMatch(t);
  const fmt = describeConfig(t.config);
  return {
    id: 'H' + (t.tid ?? now.toString(36)),
    rv: 2,
    at: now,
    fmt: fmt.ok ? fmt.text : '',
    diff: recordDiff(t),
    n: Object.keys(t.teams).length,
    champ: snap(t, t.champion!),
    vice: t.runnerUp ? snap(t, t.runnerUp) : null,
    note: t.championNote,
    final: f && f.res ? { stage: f.stage, score: scoreLine(t, f) } : null,
    users: t.userIds.map(id => ({
      ...snap(t, id), ...placementOf(t, id), st: { ...team(t, id).st }, sup: superTotal(t, id),
      live: clubMatches(t, id).filter(m => fullyLive(t, m, id)).length
    })),
    skill: t.skill ? JSON.parse(JSON.stringify(t.skill)) : undefined,
    share: buildShareText(t)
  };
}

/** Acrescenta a entrada (as 200 mais recentes) e atualiza o placar de títulos, que sobrevive à poda */
export function addHofEntry(h: Hof, e: HofEntry): Hof {
  h.list.push(e);
  if (h.list.length > 200) h.dropped = (h.dropped ?? 0) + h.list.splice(0, h.list.length - 200).length;
  const bump = (c: ClubSnap, title: boolean) => {
    const r = (h.titles[c.id] ??= { name: c.name, t: 0, f: 0 });
    r.name = c.name;
    r.f++;
    if (title) r.t++;
  };
  bump(e.champ, true);
  if (e.vice) bump(e.vice, false);
  return h;
}

const isNum = (x: unknown): x is number => typeof x === 'number' && Number.isFinite(x);
const isStr = (x: unknown): x is string => typeof x === 'string';
const isRec = (x: unknown): x is Record<string, unknown> => !!x && typeof x === 'object' && !Array.isArray(x);
const validSnap = (c: unknown): boolean => isRec(c) && isStr(c.id) && isStr(c.name) && isNum(c.ovr);
const validStats = (s: unknown): boolean => isRec(s) && ['j', 'v', 'e', 'd', 'gp', 'gc'].every(k => isNum(s[k]));
function validEntry(e: unknown): e is HofEntry {
  if (!isRec(e) || !isStr(e.id) || !isNum(e.at) || !isStr(e.fmt) || !isNum(e.n) || !isStr(e.share)) return false;
  if (!isStr(e.diff) || !(e.diff in DIFF) || !validSnap(e.champ) || !(e.vice === null || validSnap(e.vice))) return false;
  if (!(e.final === null || (isRec(e.final) && isStr(e.final.stage) && isStr(e.final.score)))) return false;
  return Array.isArray(e.users) && e.users.length > 0 && e.users.every(u => validSnap(u) && isRec(u) && isNum(u.rank) && isStr(u.label)
    && validStats(u.st) && isNum(u.sup) && isNum(u.live));
}

/** Lê a galeria guardada descartando só o que estiver malformado (nunca trava a tela da galeria) */
export function normalizeHof(x: unknown): Hof | null {
  if (!isRec(x) || x.v !== 1 || !Array.isArray(x.list)) return null;
  const titles: Hof['titles'] = {};
  if (isRec(x.titles)) Object.entries(x.titles).forEach(([id, r]) => {
    if (isRec(r) && isStr(r.name) && isNum(r.t) && isNum(r.f)) titles[id] = { name: r.name, t: r.t, f: r.f };
  });
  const list = x.list.filter(validEntry);
  list.forEach(e => { if (!e.rv) migrateRanks(e); });
  const dropped = typeof x.dropped === 'number' && x.dropped > 0 ? Math.floor(x.dropped) : undefined;
  return { v: 1, list, titles, ...(dropped ? { dropped } : {}) };
}

/** Entradas gravadas com a escala antiga de colocação: converte pela etapa (posição final de quem cai nela) */
const OLD_STAGE_PLACE: Record<string, number> = {
  'Final': 2, 'Semifinal': 3, 'Quartas de Final': 5, 'Oitavas de Final': 9, '16-avos de Final': 17, '32-avos de Final': 33,
  'Final da Lower': 3
};
/** Dupla eliminação antiga: quem caiu na rodada r da lower fica atrás de todos os que caíram depois */
function oldDePlace(e: HofEntry, label: string): number | undefined {
  const m = /^Lower · Rodada (\d+)$/.exec(label);
  if (!m) return undefined;
  const N = Number(/dupla eliminação com (\d+)/.exec(e.fmt)?.[1] ?? e.n);
  const U = Math.log2(N);
  if (!Number.isInteger(U) || U < 2) return undefined;
  const LRC = 2 * (U - 1);
  const losers = (r: number) => N / 2 ** (Math.floor((r - 1) / 2) + 2);
  let ahead = 3; // campeão, vice e quem caiu na final da lower
  for (let r = Number(m[1]) + 1; r < LRC; r++) ahead += losers(r);
  return ahead + 1;
}

/** Fase de grupos antiga: classificados ficam à frente; depois, os Nº colocados de cada grupo */
function oldGroupPlace(e: HofEntry, label: string): number | undefined {
  const m = /^(\d+)º do Grupo /.exec(label);
  const g = /(\d+) grupos? de (\d+)/.exec(e.fmt);
  const q = /(\d+) classificados/.exec(e.fmt);
  if (!m || !g || !q) return undefined;
  const groups = Number(g[1]), qualified = Number(q[1]), k = qualified / groups;
  return qualified + (Number(m[1]) - k - 1) * groups + 1;
}

/** Já está na escala nova? (posição no rótulo, ou rank que a escala antiga nunca alcança: ela ia no máximo a ~506) */
const NEW_SCALE_LABEL = /\(\d+º(–\d+º)? de \d+\)$/;
function migrateRanks(e: HofEntry): void {
  const isNew = e.users.every(u => u.rank >= 999 || NEW_SCALE_LABEL.test(u.label) || u.rank >= 1001 - Math.max(e.n, 64));
  if (isNew) { e.rv = 2; return; }
  e.users.forEach(u => {
    if (u.rank >= 999) return; // campeão e vice valem igual nas duas escalas
    const league = /^(\d+)º nos pontos corridos$/.exec(u.label);
    const place = league ? Number(league[1]) : OLD_STAGE_PLACE[u.label] ?? oldDePlace(e, u.label) ?? oldGroupPlace(e, u.label);
    // sem como saber a posição exata (fases de grupos, suíço, dupla eliminação antigos): metade de baixo da tabela
    u.rank = 1001 - (place ?? Math.ceil(e.n / 2) + 1);
  });
  e.rv = 2;
}

export const validHof = (x: unknown): x is Hof => {
  const h = normalizeHof(x);
  return !!h && h.list.length === (x as Hof).list.length && Object.keys(h.titles).length === Object.keys((x as Hof).titles ?? {}).length;
};

// ---------- Aproveitamento nos minigames ----------

export const emptySkill = (): Skill => ({ att: { n: 0, g: 0 }, def: { n: 0, g: 0 }, penS: { n: 0, g: 0, e: 0 }, penD: { n: 0, g: 0, e: 0 } });

/** Conta um lance decidido num minigame (nunca lances simulados, pulados ou interrompidos) */
export function bumpSkill(t: Tournament, kind: keyof Skill, goal: boolean, expected = 0): void {
  const s = (t.skill ??= emptySkill());
  const c = s[kind] as { n: number; g: number; e?: number };
  c.n++;
  if (goal) c.g++;
  if (kind === 'penS' || kind === 'penD') c.e = Math.round(((c.e ?? 0) + expected) * 1000) / 1000;
}
